import{_ as a,C as s,o as n,c as r,j as t,a as d,E as c,a2 as i}from"./chunks/framework.mRCPFc5l.js";const w=JSON.parse('{"title":"Svelte Kit Pages & Routes","description":"Every Inertia page in the Svelte kit with its route, access rules, layout and purpose, from sign-in and settings pages to tenants, users and setup.","frontmatter":{"title":"Svelte Kit Pages & Routes","description":"Every Inertia page in the Svelte kit with its route, access rules, layout and purpose, from sign-in and settings pages to tenants, users and setup.","head":[["link",{"rel":"canonical","href":"https://saas-laravel.com/docs/svelte/pages.html"}],["meta",{"property":"og:title","content":"Svelte Kit Pages & Routes"}],["meta",{"property":"og:description","content":"Every Inertia page in the Svelte kit with its route, access rules, layout and purpose, from sign-in and settings pages to tenants, users and setup."}],["meta",{"property":"og:url","content":"https://saas-laravel.com/docs/svelte/pages.html"}],["meta",{"name":"twitter:title","content":"Svelte Kit Pages & Routes"}],["meta",{"name":"twitter:description","content":"Every Inertia page in the Svelte kit with its route, access rules, layout and purpose, from sign-in and settings pages to tenants, users and setup."}]]},"headers":[],"relativePath":"docs/svelte/pages.md","filePath":"docs/svelte/pages.md","lastUpdated":1790486087000}'),l={name:"docs/svelte/pages.md"},p={id:"pages",tabindex:"-1"};function u(h,e,g,m,v,b){const o=s("Badge");return n(),r("div",null,[t("h1",p,[e[0]||(e[0]=d("Pages ",-1)),c(o,{type:"tip",text:"Svelte"}),e[1]||(e[1]=d()),e[2]||(e[2]=t("a",{class:"header-anchor",href:"#pages","aria-label":'Permalink to "Pages <Badge type="tip" text="Svelte" />"'},"​",-1))]),e[3]||(e[3]=i('<p>Pages live in <code>resources/js/pages</code>. The Inertia page name is the path without <code>.svelte</code>:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Inertia::render(&#39;users/Index&#39;) → resources/js/pages/users/Index.svelte</span></span></code></pre></div><p>Controllers live in <code>Modules/&lt;Module&gt;/Http/Controllers</code>.</p><div class="info custom-block"><p class="custom-block-title">INFO</p><p>Routes marked <strong>central</strong> only exist on the central domain (<code>APP_DOMAIN</code>, <code>central.only</code> middleware). Everything else works on the central domain and on tenant domains; the permission names include both variants (for example <code>View Users|View Tenant Users</code>).</p></div><h2 id="public-and-auth-pages" tabindex="-1">Public and auth pages <a class="header-anchor" href="#public-and-auth-pages" aria-label="Permalink to &quot;Public and auth pages&quot;">​</a></h2><p>Auth pages render inside <code>AuthLayout</code> (card, simple or split). Fortify registers the auth routes; <code>Modules/Auth/Providers/AuthServiceProvider.php</code> binds them to these pages.</p><table tabindex="0"><thead><tr><th>Page file</th><th>Route</th><th>Purpose</th></tr></thead><tbody><tr><td><code>Home.svelte</code></td><td><code>GET /</code> (<code>home</code>)</td><td>Landing page on the central domain. Tenant domains redirect to <code>login</code>. No layout.</td></tr><tr><td><code>auth/Login.svelte</code></td><td><code>GET /login</code> (<code>login</code>)</td><td>Email + password login, passkey login, links to reset/register when enabled for the domain</td></tr><tr><td><code>auth/Register.svelte</code></td><td><code>GET /register</code> (<code>register</code>)</td><td>Registration, when enabled for the domain</td></tr><tr><td><code>auth/ForgotPassword.svelte</code></td><td><code>GET /forgot-password</code> (<code>password.request</code>)</td><td>Request a reset link</td></tr><tr><td><code>auth/ResetPassword.svelte</code></td><td><code>GET /reset-password/{token}</code> (<code>password.reset</code>)</td><td>Set a new password</td></tr><tr><td><code>auth/VerifyEmail.svelte</code></td><td><code>GET /email/verify</code> (<code>verification.notice</code>)</td><td>Resend the verification email</td></tr><tr><td><code>auth/ConfirmPassword.svelte</code></td><td><code>GET /user/confirm-password</code> (<code>password.confirm</code>)</td><td>Re-enter password before sensitive pages</td></tr><tr><td><code>auth/TwoFactorChallenge.svelte</code></td><td><code>GET /two-factor-challenge</code> (<code>two-factor.login</code>)</td><td>TOTP code or recovery code; switches the layout title with <code>setLayoutProps</code></td></tr><tr><td><code>auth/AcceptInvitation.svelte</code></td><td><code>GET /invitation/accept</code> (<code>tenant.invitation.show</code>, tenant, signed) and <code>GET /users/invitation/{user}</code> (<code>users.invitation.show</code>, signed)</td><td>Invited tenant admin or user sets a password. <code>mode</code> prop: <code>&#39;workspace&#39;</code> or <code>&#39;user&#39;</code></td></tr><tr><td><code>auth/Maintenance.svelte</code></td><td>Rendered by <code>EnsureTenantIsNotInMaintenance</code> on tenant domains</td><td>Animated maintenance page with the custom message. No layout.</td></tr><tr><td><code>auth/Suspended.svelte</code></td><td>Rendered by <code>EnsureTenantIsNotSuspended</code> on tenant domains</td><td>Suspended workspace notice with the custom message. No layout.</td></tr></tbody></table><h2 id="app-pages" tabindex="-1">App pages <a class="header-anchor" href="#app-pages" aria-label="Permalink to &quot;App pages&quot;">​</a></h2><p>App pages render inside <code>AppLayout</code> and require <code>auth</code> + <code>verified</code>.</p><table tabindex="0"><thead><tr><th>Page file</th><th>Route</th><th>Permission</th><th>Purpose</th></tr></thead><tbody><tr><td><code>Dashboard.svelte</code></td><td><code>GET /dashboard</code> (<code>dashboard</code>, <code>Route::inertia</code>)</td><td><code>View Analytics Dashboard|View Tenant Dashboard</code></td><td>Dashboard placeholder grid</td></tr><tr><td><code>users/Index.svelte</code></td><td><code>GET /users</code> (<code>users.index</code>)</td><td><code>View Users|View Tenant Users</code></td><td>User list with search, stats, pagination, create/edit/delete, invitations, permission assignment</td></tr><tr><td><code>roles/Index.svelte</code></td><td><code>GET /roles</code> (<code>roles.index</code>)</td><td><code>View Roles|View Tenant Roles</code></td><td>Role list and create/edit/delete (system roles protected)</td></tr><tr><td><code>tenants/Index.svelte</code></td><td><code>GET /tenants</code> (<code>tenants.index</code>) — central</td><td><code>View Tenants</code></td><td>Tenant list with search, status filter and stats</td></tr><tr><td><code>tenants/Create.svelte</code></td><td><code>GET /tenants/create</code> (<code>tenants.create</code>) — central</td><td><code>Create Tenant</code></td><td>Create a tenant (company, subdomain, admin, profile data, status)</td></tr><tr><td><code>tenants/Show.svelte</code></td><td><code>GET /tenants/{tenant}</code> (<code>tenants.show</code>) — central</td><td><code>View Tenants</code></td><td>Tenant detail: edit, domains, reset admin password, resend invitation, delete</td></tr><tr><td><code>tenants/Domains.svelte</code></td><td><code>GET /tenants/domains</code> (<code>tenants.domains</code>) — central</td><td><code>View Tenants</code></td><td>All domains: filters, search, add, set primary, delete, per-domain settings and auth features</td></tr></tbody></table><h2 id="settings-pages" tabindex="-1">Settings pages <a class="header-anchor" href="#settings-pages" aria-label="Permalink to &quot;Settings pages&quot;">​</a></h2><p><code>settings/*</code> pages render inside <code>AppLayout</code> + <code>layouts/settings/Layout.svelte</code> (the Profile / Security / Appearance / Layout sub-navigation). <code>GET /settings</code> redirects to <code>/settings/profile</code>.</p><table tabindex="0"><thead><tr><th>Page file</th><th>Route</th><th>Purpose</th></tr></thead><tbody><tr><td><code>settings/Profile.svelte</code></td><td><code>GET /settings/profile</code> (<code>profile.edit</code>)</td><td>Name, email, language (&quot;Default&quot; follows the domain), email verification notice, delete account</td></tr><tr><td><code>settings/Security.svelte</code></td><td><code>GET /settings/security</code> (<code>security.edit</code>), requires password confirmation</td><td>Change password, two-factor authentication, passkeys</td></tr><tr><td><code>settings/Appearance.svelte</code></td><td><code>GET /settings/appearance</code> (<code>appearance.edit</code>, <code>Route::inertia</code>)</td><td>Light / dark / system</td></tr><tr><td><code>settings/Layout.svelte</code></td><td><code>GET /settings/layout</code> (<code>layout.edit</code>)</td><td>Personal layout: app layout, sidebar variant, collapsible mode</td></tr></tbody></table><h2 id="setup-pages" tabindex="-1">Setup pages <a class="header-anchor" href="#setup-pages" aria-label="Permalink to &quot;Setup pages&quot;">​</a></h2><p><code>setup/*</code> pages use the plain <code>AppLayout</code>; the sidebar switches to <code>setupMenus</code> while the URL starts with <code>/setup</code>. <code>GET /setup</code> redirects to <code>/setup/menus</code>.</p><table tabindex="0"><thead><tr><th>Page file</th><th>Route</th><th>Permission</th><th>Purpose</th></tr></thead><tbody><tr><td><code>setup/Menus.svelte</code></td><td><code>GET /setup/menus</code> (<code>setup.menus.index</code>)</td><td><code>View Navigation Menus|View Tenant Menus</code></td><td>Drag &amp; drop menu order (<code>sortablejs</code>), reset to defaults</td></tr><tr><td><code>setup/Layout.svelte</code></td><td><code>GET /setup/layout</code> (<code>setup.layout.index</code>)</td><td><code>Update Layout Settings|Update Tenant Layout</code></td><td>Global default app and auth layout</td></tr><tr><td><code>setup/TenantSettings.svelte</code></td><td><code>GET /setup/tenant-settings</code> (<code>setup.tenant-settings.edit</code>) — central</td><td><code>Manage Tenant Maintenance</code></td><td>Global maintenance mode for tenant workspaces</td></tr></tbody></table><h2 id="error-page" tabindex="-1">Error page <a class="header-anchor" href="#error-page" aria-label="Permalink to &quot;Error page&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Page file</th><th>Rendered by</th><th>Purpose</th></tr></thead><tbody><tr><td><code>errors/Error.svelte</code></td><td>Exception handler in <code>bootstrap/app.php</code></td><td>403, 404, 500 and 503 responses. Uses <code>AppLayout</code> for signed-in users and <code>AuthLayout</code> for guests.</td></tr></tbody></table><p>In <code>local</code> and <code>testing</code> only 403 renders this page; other statuses show Laravel&#39;s debug page.</p><h2 id="partials" tabindex="-1">Partials <a class="header-anchor" href="#partials" aria-label="Permalink to &quot;Partials&quot;">​</a></h2><p>Page-specific modals and sections live in <code>Partials/</code> next to the page:</p><table tabindex="0"><thead><tr><th>File</th><th>Used by</th></tr></thead><tbody><tr><td><code>users/Partials/UserFormModal.svelte</code></td><td>Create/edit user, &quot;Send invitation email&quot;</td></tr><tr><td><code>users/Partials/AssignUserPermissionsModal.svelte</code></td><td>Grouped permission checkboxes for one user</td></tr><tr><td><code>roles/Partials/RoleFormModal.svelte</code></td><td>Create/edit role</td></tr><tr><td><code>tenants/Partials/EditTenantModal.svelte</code></td><td>Edit tenant details and status</td></tr><tr><td><code>tenants/Partials/OrganizationDomains.svelte</code></td><td>Domains card on the tenant detail page</td></tr><tr><td><code>tenants/Partials/DomainModal.svelte</code></td><td>Add a domain</td></tr><tr><td><code>tenants/Partials/DomainSettingsModal.svelte</code></td><td>Per-domain App name and default language</td></tr><tr><td><code>tenants/Partials/DomainAuthFeaturesModal.svelte</code></td><td>Per-domain registration / password reset / verification / 2FA / passkeys toggles</td></tr><tr><td><code>tenants/Partials/ResetPasswordModal.svelte</code></td><td>Send a reset link or set the tenant admin password</td></tr><tr><td><code>tenants/Partials/MaintenanceModeForm.svelte</code></td><td>Maintenance message, secret bypass link, allowed IPs</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>Adding a page? Follow <a href="/docs/svelte/development.html#adding-a-page">Development → Adding a page</a>.</p></div>',23))])}const f=a(l,[["render",u]]);export{w as __pageData,f as default};
